{
  "doc": {
    "title": "Console Recommendations Feed API Contract — Draft v0",
    "status": "draft",
    "audience": "Console backend + Optimize recs pipeline + FE",
    "last_reviewed": "2025-02-18",
    "owners": ["Chloe Martin"],
    "reviewers": ["Aditya Rao", "Alicia Perez", "Logan Wright", "Sean Gallagher"],
    "notes": [
      "This contract is for the Console 'Recommendations' feed (MVP).",
      "Primary initial category is cache hit-rate recommendations (prefix/KV cache telemetry v2).",
      "Design goals: (1) stable identifiers and dedupe across runs, (2) pagination, (3) evidence links + minimal evidence payload for trust, (4) suppression controls with auditability."
    ]
  },
  "conventions": {
    "api_versioning": "Path versioning. v1 is MVP; any breaking field changes require v2.",
    "auth": "Console internal service-to-service auth; end-user authorization enforced by Console backend (tenant scoping).",
    "ids": {
      "recommendation_id": "Opaque stable id for a recommendation instance (per tenant).",
      "fingerprint": "Stable hash for dedupe across runs (same underlying issue). Used for bulk suppression and for FE grouping.",
      "evidence_id": "Opaque id for evidence items; may map to underlying telemetry aggregates."
    },
    "timestamps": "RFC3339 / ISO-8601, UTC. Example: 2025-02-18T21:05:11Z",
    "pagination": "Cursor-based pagination for stable ordering across updates.",
    "nulls": "Fields may be omitted if unknown; avoid explicit null unless necessary for FE.",
    "error_model": "All errors use { code, message, request_id } with optional details string (not nested)."
  },
  "endpoints": {
    "list": {
      "method": "GET",
      "path": "/v1/console/recommendations",
      "description": "List recommendations for a tenant with filters and cursor pagination.",
      "query_params": {
        "tenant_id": "string (required) — Console tenant/org id",
        "category": "string (optional) — e.g., 'cache_hit_rate'. If omitted, returns all categories.",
        "status": "string (optional) — one of: 'active' | 'suppressed' | 'resolved'. If omitted, returns active by default.",
        "include_suppressed": "boolean (optional, default false) — if true, includes suppressed items regardless of status filter.",
        "deployment_mode": "string (optional) — 'hosted' | 'dedicated' | 'private'",
        "region": "string (optional) — e.g., 'us-east-1'.",
        "route_id": "string (optional) — Redwood route identifier.",
        "model": "string (optional) — model family/catalog key (NOT full version) to keep cardinality bounded.",
        "model_version": "string (optional) — if provided, used only for filtering, not used as a grouping key.",
        "min_severity": "string (optional) — 'info' | 'warning' | 'critical'.",
        "page_size": "integer (optional, default 25, max 100)",
        "cursor": "string (optional) — opaque cursor from previous response.",
        "sort": "string (optional, default '-rank') — supported: '-rank', '-last_seen_at', '-created_at'"
      },
      "response": {
        "http_status": 200,
        "body": "RecommendationListResponse"
      }
    },
    "get": {
      "method": "GET",
      "path": "/v1/console/recommendations/{recommendation_id}",
      "description": "Fetch a single recommendation by id (includes expanded evidence payload by default).",
      "path_params": {
        "recommendation_id": "string (required)"
      },
      "query_params": {
        "tenant_id": "string (required)",
        "expand": "string (optional) — comma-separated expansions. Supported: 'evidence', 'history'. Default: 'evidence'."
      },
      "response": {
        "http_status": 200,
        "body": "RecommendationGetResponse"
      }
    },
    "suppress": {
      "method": "POST",
      "path": "/v1/console/recommendations/{recommendation_id}/suppress",
      "description": "Suppress a recommendation. Suppression may be applied to the instance id or to a fingerprint (recommended).",
      "path_params": {
        "recommendation_id": "string (required)"
      },
      "body": "RecommendationSuppressRequest",
      "response": {
        "http_status": 200,
        "body": "RecommendationSuppressResponse"
      }
    },
    "unsuppress": {
      "method": "POST",
      "path": "/v1/console/recommendations/{recommendation_id}/unsuppress",
      "description": "Remove suppression (for the specific recommendation id or for its fingerprint, depending on original scope).",
      "path_params": {
        "recommendation_id": "string (required)"
      },
      "body": "RecommendationUnsuppressRequest",
      "response": {
        "http_status": 200,
        "body": "RecommendationUnsuppressResponse"
      }
    },
    "bulk_suppress": {
      "method": "POST",
      "path": "/v1/console/recommendations/bulk/suppress",
      "description": "Bulk suppress by fingerprint list (MVP: max 50 per request).",
      "body": "RecommendationBulkSuppressRequest",
      "response": {
        "http_status": 200,
        "body": "RecommendationBulkSuppressResponse"
      }
    }
  },
  "schemas": {
    "RecommendationListResponse": {
      "type": "object",
      "required": ["request_id", "items", "page"],
      "properties": {
        "request_id": {"type": "string"},
        "items": {"type": "array", "items": {"$ref": "#/schemas/Recommendation"}},
        "page": {"$ref": "#/schemas/PageInfo"}
      }
    },
    "RecommendationGetResponse": {
      "type": "object",
      "required": ["request_id", "item"],
      "properties": {
        "request_id": {"type": "string"},
        "item": {"$ref": "#/schemas/Recommendation"}
      }
    },
    "PageInfo": {
      "type": "object",
      "required": ["page_size", "has_more"],
      "properties": {
        "page_size": {"type": "integer"},
        "cursor": {"type": "string", "description": "Echo of request cursor, if any."},
        "next_cursor": {"type": "string", "description": "Omit if has_more=false."},
        "has_more": {"type": "boolean"}
      }
    },
    "Recommendation": {
      "type": "object",
      "required": [
        "recommendation_id",
        "tenant_id",
        "category",
        "type",
        "title",
        "summary",
        "severity",
        "rank",
        "status",
        "created_at",
        "last_seen_at",
        "fingerprint"
      ],
      "properties": {
        "recommendation_id": {"type": "string"},
        "tenant_id": {"type": "string"},
        "fingerprint": {"type": "string", "description": "Stable hash for dedupe and suppression scope."},
        "category": {"type": "string", "enum": ["cache_hit_rate"]},
        "type": {
          "type": "string",
          "enum": [
            "prompt_prefix_diversity",
            "routing_fragmentation",
            "cache_policy_mismatch",
            "model_version_fragmentation"
          ]
        },
        "title": {"type": "string"},
        "summary": {"type": "string", "description": "Short plaintext summary for feed row."},
        "severity": {"type": "string", "enum": ["info", "warning", "critical"]},
        "confidence": {"type": "string", "enum": ["low", "medium", "high"], "description": "Heuristic confidence."},
        "rank": {"type": "number", "description": "Higher = more important. Used for default sorting."},
        "status": {"type": "string", "enum": ["active", "suppressed", "resolved"]},
        "created_at": {"type": "string"},
        "last_seen_at": {"type": "string", "description": "Last time this fingerprint was observed in telemetry window."},
        "updated_at": {"type": "string"},
        "expires_at": {"type": "string", "description": "When the rec should auto-hide if not seen again. Optional."},
        "scope": {"$ref": "#/schemas/RecommendationScope"},
        "impact": {"$ref": "#/schemas/RecommendationImpact"},
        "actions": {"type": "array", "items": {"$ref": "#/schemas/RecommendationAction"}},
        "evidence": {"type": "array", "items": {"$ref": "#/schemas/EvidenceItem"}},
        "links": {"type": "array", "items": {"$ref": "#/schemas/Link"}},
        "suppression": {"$ref": "#/schemas/SuppressionState"}
      }
    },
    "RecommendationScope": {
      "type": "object",
      "required": ["deployment_mode"],
      "properties": {
        "deployment_mode": {"type": "string", "enum": ["hosted", "dedicated", "private"]},
        "region": {"type": "string"},
        "route_id": {"type": "string"},
        "route_name": {"type": "string"},
        "model": {"type": "string"},
        "model_version": {"type": "string"},
        "workspace": {"type": "string", "description": "Optional for enterprise orgs with multiple workspaces."}
      }
    },
    "RecommendationImpact": {
      "type": "object",
      "required": [],
      "properties": {
        "estimated_saved_prefill_ms_p50": {"type": "number"},
        "estimated_saved_prefill_ms_p95": {"type": "number"},
        "estimated_saved_tokens_per_day": {"type": "number"},
        "estimated_cost_savings_usd_per_day": {"type": "number"},
        "window": {"type": "string", "description": "e.g., '24h', '7d'."}
      },
      "description": "All impact fields are best-effort estimates and may be omitted if insufficient data."
    },
    "RecommendationAction": {
      "type": "object",
      "required": ["action_id", "label"],
      "properties": {
        "action_id": {"type": "string", "description": "Opaque id; FE sends back on feedback events in future iteration."},
        "label": {"type": "string", "description": "Short CTA text."},
        "action_type": {
          "type": "string",
          "enum": [
            "open_docs",
            "open_dashboard",
            "open_route_settings",
            "contact_support",
            "view_sample_prefixes"
          ]
        },
        "url": {"type": "string"}
      }
    },
    "EvidenceItem": {
      "type": "object",
      "required": ["evidence_id", "kind", "title"],
      "properties": {
        "evidence_id": {"type": "string"},
        "kind": {
          "type": "string",
          "enum": [
            "metric_snapshot",
            "timeseries_link",
            "top_k_table_link",
            "query_link",
            "note"
          ]
        },
        "title": {"type": "string"},
        "summary": {"type": "string"},
        "metric_name": {"type": "string", "description": "If kind=metric_snapshot."},
        "metric_value": {"type": "number", "description": "If kind=metric_snapshot."},
        "metric_unit": {"type": "string", "description": "e.g., 'ratio', 'ms', 'bytes'."},
        "window": {"type": "string", "description": "e.g., '1h', '24h', '7d'."},
        "url": {"type": "string", "description": "Link to Console dashboard panel or internal explore."},
        "query": {"type": "string", "description": "Human-readable query or query id. Avoid embedding PII. Optional."},
        "dataset": {"type": "string", "description": "Dataset/source name. Optional."}
      }
    },
    "Link": {
      "type": "object",
      "required": ["label", "url"],
      "properties": {
        "label": {"type": "string"},
        "url": {"type": "string"}
      }
    },
    "SuppressionState": {
      "type": "object",
      "required": [],
      "properties": {
        "is_suppressed": {"type": "boolean"},
        "scope": {"type": "string", "enum": ["recommendation_id", "fingerprint"], "description": "How suppression is applied."},
        "suppressed_by": {"type": "string", "description": "Actor id/email (Console user) or service name."},
        "suppressed_at": {"type": "string"},
        "suppress_until": {"type": "string", "description": "If omitted, suppression is indefinite until unsuppressed."},
        "reason": {"type": "string"}
      }
    },
    "RecommendationSuppressRequest": {
      "type": "object",
      "required": ["tenant_id"],
      "properties": {
        "tenant_id": {"type": "string"},
        "scope": {"type": "string", "enum": ["recommendation_id", "fingerprint"], "default": "fingerprint"},
        "suppress_until": {"type": "string", "description": "RFC3339 timestamp; optional."},
        "reason": {"type": "string", "description": "Freeform; FE should offer presets but allow custom."},
        "actor": {"type": "string", "description": "Console user id/email. Set by backend if not provided."}
      }
    },
    "RecommendationSuppressResponse": {
      "type": "object",
      "required": ["request_id", "recommendation_id", "status"],
      "properties": {
        "request_id": {"type": "string"},
        "recommendation_id": {"type": "string"},
        "status": {"type": "string", "enum": ["suppressed"]}
      }
    },
    "RecommendationUnsuppressRequest": {
      "type": "object",
      "required": ["tenant_id"],
      "properties": {
        "tenant_id": {"type": "string"},
        "scope": {"type": "string", "enum": ["recommendation_id", "fingerprint"], "description": "Should match original suppression scope when possible."},
        "reason": {"type": "string"},
        "actor": {"type": "string"}
      }
    },
    "RecommendationUnsuppressResponse": {
      "type": "object",
      "required": ["request_id", "recommendation_id", "status"],
      "properties": {
        "request_id": {"type": "string"},
        "recommendation_id": {"type": "string"},
        "status": {"type": "string", "enum": ["active"]}
      }
    },
    "RecommendationBulkSuppressRequest": {
      "type": "object",
      "required": ["tenant_id", "fingerprints"],
      "properties": {
        "tenant_id": {"type": "string"},
        "fingerprints": {"type": "array", "items": {"type": "string"}, "maxItems": 50},
        "suppress_until": {"type": "string"},
        "reason": {"type": "string"},
        "actor": {"type": "string"}
      }
    },
    "RecommendationBulkSuppressResponse": {
      "type": "object",
      "required": ["request_id", "results"],
      "properties": {
        "request_id": {"type": "string"},
        "results": {
          "type": "array",
          "items": {
            "type": "object",
            "required": ["fingerprint", "status"],
            "properties": {
              "fingerprint": {"type": "string"},
              "status": {"type": "string", "enum": ["suppressed", "already_suppressed", "not_found"]}
            }
          }
        }
      }
    }
  },
  "examples": {
    "list_request": "GET /v1/console/recommendations?tenant_id=tnt_9f3a&category=cache_hit_rate&deployment_mode=dedicated&region=us-east-1&page_size=25",
    "list_response": {
      "request_id": "req_01JMYE8PZ8Y7X1WQJ6J9K0K3T0",
      "items": [
        {
          "recommendation_id": "rec_01JMYE8X6QH4N2B7GQ9E0R3W1K",
          "tenant_id": "tnt_9f3a",
          "fingerprint": "fp_cachehit_routingfrag_7b3c1fbd",
          "category": "cache_hit_rate",
          "type": "routing_fragmentation",
          "title": "Reduce routing fragmentation to improve prefix cache hit-rate",
          "summary": "Traffic is split across 4 model variants for the same route, reducing cache reuse. Pin or consolidate routing where possible.",
          "severity": "warning",
          "confidence": "medium",
          "rank": 0.82,
          "status": "active",
          "created_at": "2025-02-15T18:04:10Z",
          "last_seen_at": "2025-02-18T20:59:44Z",
          "updated_at": "2025-02-18T21:05:11Z",
          "scope": {
            "deployment_mode": "dedicated",
            "region": "us-east-1",
            "route_id": "route_2kQp1m",
            "route_name": "chat-prod",
            "model": "llama-3.1-70b"
          },
          "impact": {
            "estimated_saved_prefill_ms_p50": 38.2,
            "estimated_saved_prefill_ms_p95": 121.7,
            "estimated_saved_tokens_per_day": 1900000,
            "estimated_cost_savings_usd_per_day": 74.3,
            "window": "24h"
          },
          "actions": [
            {
              "action_id": "act_open_route_settings",
              "label": "Review route routing/pinning",
              "action_type": "open_route_settings",
              "url": "https://console.redwoodinference.com/tenant/tnt_9f3a/routes/route_2kQp1m"
            },
            {
              "action_id": "act_open_dashboard",
              "label": "Open cache hit-rate dashboard",
              "action_type": "open_dashboard",
              "url": "https://console.redwoodinference.com/tenant/tnt_9f3a/observability/cache"
            }
          ],
          "evidence": [
            {
              "evidence_id": "ev_01JMYE9B6Z9H2AZ0V3Z62Z1K4D",
              "kind": "metric_snapshot",
              "title": "Cache hit-rate (route)",
              "summary": "Hit-rate is 0.21 over last 24h; peers for similar traffic mix are 0.45–0.60.",
              "metric_name": "kv_cache.hit_rate",
              "metric_value": 0.21,
              "metric_unit": "ratio",
              "window": "24h",
              "url": "https://console.redwoodinference.com/tenant/tnt_9f3a/observability/cache?route_id=route_2kQp1m"
            },
            {
              "evidence_id": "ev_01JMYE9Q2JAX8H6JX9X1F5Q8QW",
              "kind": "timeseries_link",
              "title": "Hit-rate over time",
              "summary": "Drop correlates with rollout to additional model variants.",
              "url": "https://console.redwoodinference.com/tenant/tnt_9f3a/observability/cache?route_id=route_2kQp1m&view=timeseries"
            }
          ],
          "links": [
            {"label": "Docs: Improving cache hit-rate", "url": "https://docs.redwoodinference.com/optimize/cache-hit-rate"}
          ],
          "suppression": {"is_suppressed": false}
        }
      ],
      "page": {
        "page_size": 25,
        "has_more": false
      }
    }
  },
  "open_questions": [
    "Do we need a separate endpoint for feedback (thumbs up/down, dismissed, implemented)? Not in MVP but suggested for v1.1.",
    "Should 'resolved' be computed by the rec engine (no longer observed) vs user action? Current: engine sets resolved when fingerprint not seen for N days.",
    "Evidence payload size: should list endpoint return evidence by default or only a small subset (first 1–2 items) to keep feed fast? Current: return evidence array but keep it small for list; full details via GET by id.",
    "Suppression scope default is fingerprint. Need to confirm with FE UX (suppress this vs suppress all like this).",
    "Authorization: tenant_id in query/body is required for now; backend may infer from auth context later.",
    "Need alignment with telemetry v2 tag constraints: model_version should be filter-only and not used for grouping/fingerprint unless explicitly required.",
    "Private deployments: confirm that URLs in evidence can point to customer-hosted Console domains; may need relative paths." 
  ],
  "non_goals": [
    "No customer-configurable policy engine for recommendations in MVP.",
    "No guarantee that recommendation rank is stable across releases.",
    "No per-request evidence (no request_id lists) to avoid cardinality/PII risks." 
  ]
}
